    CREATE FUNCTION crove_jobs.job_table_format(command text, table_name text)
    RETURNS text AS
    $$
      SELECT format(
        regexp_replace(
          regexp_replace(command, '\.job\y', '.%1$I', 'g'),
          '\yjob_i(\d+)', '%1$s_i\1', 'g'
        ),
        table_name
      );
    $$
    LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp;
  ;

    CREATE FUNCTION crove_jobs.job_table_run(command text, tbl_name text DEFAULT NULL, queue_name text DEFAULT NULL)
    RETURNS VOID AS
    $$
    DECLARE
      tbl RECORD;
    BEGIN
      IF queue_name IS NOT NULL THEN
        SELECT table_name INTO tbl_name FROM crove_jobs.queue WHERE name = queue_name;
      END IF;

      IF tbl_name IS NOT NULL THEN
        EXECUTE crove_jobs.job_table_format(command, tbl_name);
        RETURN;
      END IF;

      EXECUTE crove_jobs.job_table_format(command, 'job_common');

      FOR tbl IN SELECT table_name FROM crove_jobs.queue WHERE partition = true
      LOOP
        EXECUTE crove_jobs.job_table_format(command, tbl.table_name);
      END LOOP;
    END;
    $$
    LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp;
  ;

    CREATE FUNCTION crove_jobs.job_table_run_async(command_name text, version int, command text, tbl_name text DEFAULT NULL, queue_name text DEFAULT NULL)
    RETURNS VOID AS
    $$
    BEGIN
      IF queue_name IS NOT NULL THEN
        SELECT table_name INTO tbl_name FROM crove_jobs.queue WHERE name = queue_name;
      END IF;

      IF tbl_name IS NOT NULL THEN
        INSERT INTO crove_jobs.bam (name, version, status, queue, table_name, command)
        VALUES (
          command_name,
          version,
          'pending',
          queue_name,
          tbl_name,
          crove_jobs.job_table_format(command, tbl_name)
        );
        RETURN;
      END IF;

      INSERT INTO crove_jobs.bam (name, version, status, queue, table_name, command)
      SELECT
        command_name,
        version,
        'pending',
        NULL,
        'job_common',
        crove_jobs.job_table_format(command, 'job_common')
      UNION ALL
      SELECT
        command_name,
        version,
        'pending',
        queue.name,
        queue.table_name,
        crove_jobs.job_table_format(command, queue.table_name)
      FROM crove_jobs.queue
      WHERE partition = true;
    END;
    $$
    LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp;
  ;

