    CREATE FUNCTION crove_jobs.create_queue(queue_name text, options jsonb)
    RETURNS VOID AS
    $$
    DECLARE
      tablename varchar := CASE WHEN options->>'partition' = 'true'
                            THEN 'j' || encode(sha224(queue_name::bytea), 'hex')
                            ELSE 'job_common'
                            END;
      queue_created_on timestamptz;
    BEGIN

      WITH q as (
        INSERT INTO crove_jobs.queue (
          name,
          policy,
          retry_limit,
          retry_delay,
          retry_backoff,
          retry_delay_max,
          expire_seconds,
          retention_seconds,
          deletion_seconds,
          warning_queued,
          dead_letter,
          partition,
          table_name,
          heartbeat_seconds,
          notify,
          created_on,
          updated_on
        )
        VALUES (
          queue_name,
          options->>'policy',
          COALESCE((options->>'retryLimit')::int, 2),
          COALESCE((options->>'retryDelay')::int, 0),
          COALESCE((options->>'retryBackoff')::bool, false),
          (options->>'retryDelayMax')::int,
          COALESCE((options->>'expireInSeconds')::int, 900),
          COALESCE((options->>'retentionSeconds')::int, 1209600),
          COALESCE((options->>'deleteAfterSeconds')::int, 604800),
          COALESCE((options->>'warningQueueSize')::int, 0),
          options->>'deadLetter',
          COALESCE((options->>'partition')::bool, false),
          tablename,
          (options->>'heartbeatSeconds')::int,
          COALESCE((options->>'notify')::bool, false),
          crove_jobs.job_now(),
          crove_jobs.job_now()
        )
        ON CONFLICT DO NOTHING
        RETURNING created_on
      )
      SELECT created_on into queue_created_on from q;

      IF queue_created_on IS NULL OR options->>'partition' IS DISTINCT FROM 'true' THEN
        RETURN;
      END IF;

      EXECUTE format('CREATE TABLE crove_jobs.%I (LIKE crove_jobs.job INCLUDING DEFAULTS)', tablename);

      EXECUTE crove_jobs.job_table_format($cmd$ALTER TABLE crove_jobs.job ADD PRIMARY KEY (name, id)$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$ALTER TABLE crove_jobs.job ADD CONSTRAINT q_fkey FOREIGN KEY (name) REFERENCES crove_jobs.queue (name) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$ALTER TABLE crove_jobs.job ADD CONSTRAINT dlq_fkey FOREIGN KEY (dead_letter) REFERENCES crove_jobs.queue (name) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED$cmd$, tablename);

      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i11 ON crove_jobs.job (name, priority DESC, created_on, start_after) WHERE state < 'active' AND NOT blocked$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE UNIQUE INDEX job_i4 ON crove_jobs.job (name, singleton_on, COALESCE(singleton_key, '')) WHERE state <> 'cancelled' AND singleton_on IS NOT NULL$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i7 ON crove_jobs.job (name, group_id) WHERE state = 'active' AND group_id IS NOT NULL$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i9 ON crove_jobs.job (name, id) WHERE blocking AND state = 'completed'$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i12 ON crove_jobs.job (source_root_id) WHERE source_root_id IS NOT NULL$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE UNIQUE INDEX job_i13 ON crove_jobs.job (name, singleton_key) WHERE state = 'created' AND upsert_by_key$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i14 ON crove_jobs.job (name, state, blocked, start_after) WHERE state IN ('created', 'retry', 'active', 'failed')$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i15 ON crove_jobs.job (name, created_on)$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i16 ON crove_jobs.job (name, completed_on) WHERE completed_on IS NOT NULL$cmd$, tablename);
      EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i17 ON crove_jobs.job (name, singleton_key, created_on) WHERE state < 'active' AND singleton_key IS NOT NULL$cmd$, tablename);

      IF options->>'policy' = 'short' THEN
        EXECUTE crove_jobs.job_table_format($cmd$CREATE UNIQUE INDEX job_i1 ON crove_jobs.job (name, COALESCE(singleton_key, '')) WHERE state = 'created' AND policy = 'short'$cmd$, tablename);
      ELSIF options->>'policy' = 'singleton' THEN
        EXECUTE crove_jobs.job_table_format($cmd$CREATE UNIQUE INDEX job_i2 ON crove_jobs.job (name, COALESCE(singleton_key, '')) WHERE state = 'active' AND policy = 'singleton'$cmd$, tablename);
      ELSIF options->>'policy' = 'stately' THEN
        EXECUTE crove_jobs.job_table_format($cmd$CREATE UNIQUE INDEX job_i3 ON crove_jobs.job (name, state, COALESCE(singleton_key, '')) WHERE state <= 'active' AND policy = 'stately'$cmd$, tablename);
      ELSIF options->>'policy' = 'exclusive' THEN
        EXECUTE crove_jobs.job_table_format($cmd$CREATE UNIQUE INDEX job_i6 ON crove_jobs.job (name, COALESCE(singleton_key, '')) WHERE state <= 'active' AND policy = 'exclusive'$cmd$, tablename);
      ELSIF options->>'policy' = 'key_strict_fifo' THEN
        EXECUTE crove_jobs.job_table_format($cmd$CREATE UNIQUE INDEX job_i8 ON crove_jobs.job (name, singleton_key) WHERE state IN ('active', 'retry', 'failed') AND policy = 'key_strict_fifo'$cmd$, tablename);
        EXECUTE crove_jobs.job_table_format($cmd$CREATE INDEX job_i10 ON crove_jobs.job (name, singleton_key, state DESC, created_on, id) INCLUDE (start_after) WHERE state < 'active' AND NOT blocked AND policy = 'key_strict_fifo'$cmd$, tablename);
        EXECUTE crove_jobs.job_table_format($cmd$ALTER TABLE crove_jobs.job ADD CONSTRAINT job_key_strict_fifo_singleton_key_check CHECK (NOT (policy = 'key_strict_fifo' AND singleton_key IS NULL))$cmd$, tablename);
      END IF;

      EXECUTE format('ALTER TABLE crove_jobs.%I ADD CONSTRAINT cjc CHECK (name=%L)', tablename, queue_name);
      EXECUTE format('ALTER TABLE crove_jobs.job ATTACH PARTITION crove_jobs.%I FOR VALUES IN (%L)', tablename, queue_name);
    END;
    $$
    LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp;
  ;

    CREATE FUNCTION crove_jobs.delete_queue(queue_name text)
    RETURNS VOID AS
    $$
    DECLARE
      v_table varchar;
      v_partition bool;
    BEGIN
      
      SELECT table_name, partition
      FROM crove_jobs.queue
      WHERE name = queue_name
      INTO v_table, v_partition;

      IF v_partition THEN
        EXECUTE format('DROP TABLE IF EXISTS crove_jobs.%I', v_table);
      ELSE
        EXECUTE format('DELETE FROM crove_jobs.%I WHERE name = %L', v_table, queue_name);
      END IF;
    
      DELETE FROM crove_jobs.queue WHERE name = queue_name;
    END;
    $$
    LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp;
  ;
INSERT INTO crove_jobs.version(version) VALUES ('46');
$pgboss$;
  END IF;
END
$vendor$;

-- A schema pg-boss created at runtime (before #25) has functions without a pinned search_path. The migration role
-- created them then, so it owns them now.
DO $pin$
DECLARE
  fn regprocedure;
BEGIN
  FOR fn IN
    SELECT p.oid::regprocedure FROM pg_catalog.pg_proc p
     WHERE p.pronamespace = 'crove_jobs'::regnamespace
       AND p.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, pg_temp']
  LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path = pg_catalog, pg_temp', fn);
  END LOOP;
END
$pin$;

-- Queues the worker uses (QUEUES in apps/kernel/src/jobs-schema.ts); create_queue skips existing ones.
SELECT crove_jobs.create_queue(q, '{"policy":"standard"}'::jsonb) FROM unnest(ARRAY['finance-file-extract', 'kernel-inbound-email', 'kernel-session-signout', 'kernel-org-export', 'kernel-retention-purge', 'kernel-agent-dispatch', 'kernel-agent-sweep']) AS q;
SELECT crove_jobs.create_queue(q, '{"policy":"stately"}'::jsonb) FROM unnest(ARRAY['kernel-agent-wake']) AS q;

-- /readyz (the API role) compares this with the version its pg-boss expects.
CREATE OR REPLACE FUNCTION crove_kernel.jobs_schema_version()
RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT max(v.version) FROM crove_jobs.version v
$$;
REVOKE ALL ON FUNCTION crove_kernel.jobs_schema_version() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION crove_kernel.jobs_schema_version() TO crove_app;

-- The worker (pg-boss and the outbox relay) uses crove_jobs; nobody else may.
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA crove_jobs FROM PUBLIC;
GRANT USAGE ON SCHEMA crove_jobs TO crove_worker;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA crove_jobs TO crove_worker;
-- The version row decides whether a vendored upgrade runs, so only migrations write it. pg-boss started with
-- migrate: false only stamps its maintenance columns.
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON crove_jobs.version FROM crove_worker;
GRANT UPDATE (cron_on, bam_on, flow_on, reindex_on, monitor_backoff_on) ON crove_jobs.version TO crove_worker;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA crove_jobs TO crove_worker;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA crove_jobs TO crove_worker;
ALTER DEFAULT PRIVILEGES IN SCHEMA crove_jobs GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO crove_worker;
